def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict with 'x' and 'y' coordinates or None
    """
    if value is None:
        return None

    # Helper to convert coordinate to float
    def _to_float(val):
        try:
            return float(val)
        except (TypeError, ValueError):
            raise ValueError(f"Coordinate '{val}' cannot be converted to float")

    # 1. If value is a tuple or list
    if isinstance(value, (tuple, list)):
        if len(value) >= 2:
            x, y = value[0], value[1]
            return {'x': _to_float(x), 'y': _to_float(y)}
        else:
            raise ValueError("Point tuple/list must contain at least two elements")

    # 2. Try accessing 'x' and 'y' attributes
    try:
        x = getattr(value, 'x')
        y = getattr(value, 'y')
        return {'x': _to_float(x), 'y': _to_float(y)}
    except AttributeError:
        pass

    # 3. Try accessing a 'coords' or 'coordinates' attribute
    for attr_name in ('coords', 'coordinates'):
        if hasattr(value, attr_name):
            coords = getattr(value, attr_name)
            if isinstance(coords, (tuple, list, set)):
                if len(coords) >= 2:
                    x, y = coords[0], coords[1]
                    return {'x': _to_float(x), 'y': _to_float(y)}
            break

    # If all attempts fail, raise an informative error
    raise ValueError(f"Cannot dehydrate object of type {type(value).__name__} as a Point")
