def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # Assume the record is stored in self._record as an ordered dict-like
        # mapping.  If no keys are supplied, return all values in order.
        if not hasattr(self, "_record"):
            raise AttributeError("The object has no '_record' attribute to fetch values from.")

        # Handle the case of an empty record gracefully.
        try:
            record_values = list(self._record.values())
        except Exception as exc:
            raise TypeError(f"Could not obtain values from '_record': {exc}") from exc

        if not keys:
            return record_values

        result = []
        for key in keys:
            # Integer keys are treated as index positions.
            if isinstance(key, int):
                try:
                    result.append(record_values[key])
                except IndexError as exc:
                    raise IndexError(f"Index {key} is out of bounds for values of the record.") from exc
            else:
                # Non-integer keys are treated as dictionary keys.
                if key in self._record:
                    result.append(self._record[key])
                else:
                    raise KeyError(f"Key {key!r} not found in the record.")
        return result<|return|>

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # The record is expected to hold two attributes: `_keys` (list of field names)
    # and `_values` (corresponding list of values).  If these are not present,
    # we raise an AttributeError to signal misuse of the method.
    try:
        keys_list = self._keys
        values_list = self._values
    except AttributeError as exc:
        raise AttributeError(
            "Record object must provide `_keys` and `_values` attributes."
        ) from exc

    # If no keys are specified, return all key/value pairs.
    if not keys:
        return dict(zip(keys_list, values_list))

    # Build the resulting dictionary according to the supplied keys.
    result = {}
    for key in keys:
        # Handle integer indices.
        if isinstance(key, int):
            # Allow negative indices within the bounds of the list.
            if key < -len(values_list) or key >= len(values_list):
                raise IndexError(f"Index {key} out of bounds")
            idx = key
            result[keys_list[idx]] = values_list[idx]
        # Handle string keys; insert None for missing keys.
        elif isinstance(key, str):
            if key in keys_list:
                idx = keys_list.index(key)
                result[key] = values_list[idx]
            else:
                result[key] = None
        else:
            # Unsupported key type: raise a TypeError for clarity.
            raise TypeError(
                f"Unsupported key type {type(key).__name__}; "
                "expected int or str."
