def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    nums = []
    cur = ""
    for ch in s:
        if ch.isdigit():
            cur += ch
        else:
            if cur:
                try:
                    nums.append(int(cur))
                except ValueError:
                    # In case cur is too large; fallback to ignoring this chunk
                    pass
                cur = ""
    if cur:
        try:
            nums.append(int(cur))
        except ValueError:
            pass
    return tuple(nums)<|return|>

