def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        cls_name = self.__class__.__name__
        for suffix in ("Py", "Fallback"):
            if cls_name.endswith(suffix):
                return cls_name[: -len(suffix)]
        return cls_name
    except Exception as exc:
        # If something unexpected happens we raise a RuntimeError
        # to provide a clear error context to the caller.
        raise RuntimeError(f"Unable to determine target class: {exc}") from exc<|return|>

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.  If the
    object has no directly declared interfaces, an empty ``IDeclaration`` (i.e.
    an empty ``dict``) is returned.
    """
    try:
        # `__provides__` holds the mapping of directly provided interfaces.
        provides = getattr(object, "__provides__", None)
        if provides is None:
            # No attribute present – nothing provided.
            return {}
        # If we already have an IDeclaration instance, return it unchanged.
        try:
            from zope.interface.interfaces import IDeclaration
            if isinstance(provides, IDeclaration):
                return provides
        except Exception:
            # zope.interface may not be present; fall back to plain mapping.
            pass
        # If the attribute is a plain dict or other mapping, return it directly
        # (this mimics the IDeclaration API which is a dict subclass).
        if isinstance(provides, dict):
            return provides
        # Fallback: attempt to coerce into an IDeclaration if possible
        try:
            from zope.interface.interfaces import IDeclaration
            return IDeclaration(provides)
        except Exception:
            # Cannot interpret the value – fall back to empty mapping.
            return {}
    except Exception:
        # Any unexpected error results in an empty declaration to keep
        # the API robust and avoid propagating unexpected exceptions.
        return {}<|return|>

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Retrieve interface definition if present
    interface = getattr(self, 'interface', None)
    result = {}
    if isinstance(interface, dict):
        for name, item in interface.items():
            # Determine description based on type of interface entry
            if isinstance(item, str):
                desc = item
            elif hasattr(item, 'description'):
                desc = getattr(item, 'description', str(item))
            elif callable(item):
                try:
                    desc = item()
                except Exception:
                    desc = repr(item)
            else:
                desc = str(item)
            result[name] = desc
    # If requested, include all other attributes not in the interface
    if all:
        for attr_name in dir(self):
            # Skip private/internal names
            if attr_name.startswith('_'):
                continue
            if attr_name in result:
                continue
            try:
                value = getattr(self, attr_name)
                # If it's a callable with a docstring, use that
                if callable(value) and getattr(value, "__doc__", None):
                    desc = value.__doc__.strip()
                else:
                    desc = str(value)
                result[attr_name] = desc
            except Exception:
                # Skip attributes that raise errors to keep method robust
                continue
    return result<|return|>

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    try:
        self.context = {}
    except Exception:
        # If the attribute does not exist, create it
        setattr(self, "context", {})

    # Reinitialize bins
    try:
        # If an initial value was provided at initialization
        if hasattr(self, "initial_value"):
            # Reset each existing bin to the initial value if bins is list-like
            if hasattr(self, "bins"):
                if isinstance(self.bins, list):
                    for i in range(len(self.bins)):
                        self.bins[i] = self.initial_value
                else:
                    # For non-list bins (e.g., numpy array), create a new array
                    self.bins = self.initial_value
        # If no initial value, but make_bins is defined, use it to re-create bins
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        # If neither attribute is present, do nothing
    except Exception:
        # In case something goes wrong, attempt a fallback using make_bins
        if hasattr(self, "make_bins") and callable(self.make_bins):
            try:
                self.bins = self.make_bins()
            except Exception:
                # Give up silently if even make_bins fails
                pass<|return|>

def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates, if they are present),
    which allows to simplify plotting.
    Existing values are not removed from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    try:
        # Ensure the context has an 'error' dictionary
        if isinstance(context, dict):
            errors = context.setdefault('error', {})
        else:
            errors = getattr(context, 'error', None)
            if errors is None:
                errors = {}
                setattr(context, 'error', errors)

        # Iterate over attributes that represent error indices
        for attr in dir(self):
            # Skip private/dunder attributes and non-error fields
            if not attr.startswith('error_') or attr.startswith('__'):
                continue
            # Retrieve the value; it could be an index or a data structure
            val = getattr(self, attr)
            # Construct the key used in the subcontext
            suffix = attr[6:]  # everything after 'error_'
            # Map the first character to coordinate names (E->x, t->y, z->z)
            if suffix:
                first_char = suffix[0].lower()
                if first_char == 'e':
                    suffix = 'x' + suffix[1:]
                elif first_char == 't':
                    suffix = 'y' + suffix[1:]
                elif first_char == 'z':
                    suffix = 'z' + suffix[1:]
            # Resolve an index from the value
            if isinstance(val, (int, float)):
                index = val
            else:
                try:
                    index = int(val)
                except Exception:
                    # Cannot determine an index; skip this attribute
                    continue
            # Append the subcontext information
            errors[suffix] = {'index': index}
    except Exception as exc:
        # In case of any error, capture it in the context for debugging
        err_dict = getattr(context, 'error', None) if not isinstance(context, dict) else context.get('error', None)
        if err_dict is None:
            err_dict = {}
            if isinstance(context, dict):
                context['error'] = err_dict
            else:
                setattr(context, 'error', err_dict)
        err_dict.setdefault('update_context', []).append(str(exc))<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic input validation
    if bins is None or edges is None:
        raise ValueError("Both bins and edges must be provided and not None.")
    # Convert to list if not already, support tuples, numpy arrays, etc.
    try:
        bins_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable of numerical values.")
    try:
        edges_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable of numerical values.")
    if len(edges_list) == 0:
        raise ValueError("edges cannot be empty; it must contain at least one bin edge.")
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError(
            f"Inconsistent lengths: bins has {len(bins_list)} elements while edges has {len(edges_list)} elements "
            f"(edges should have one more element than bins)."
        )
    # Compute the integral as the sum of bin values times bin widths
    total = 0.0
    for bin_val, left_edge, right_edge in zip(bins_list, edges_list, edges_list[1:]):
        try:
            width = right_edge - left_edge
            total += float(bin_val) * float(width)
        except Exception as e:
            raise ValueError(f"Error computing integral for bin value {bin_val} with edges {left_edge}-{right_edge}: {e}") from e
    return total

