def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Check if seq itself is a single FillRequest
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest type not available; skip this check
        pass

    # Ensure seq is not a Source sequence
    try:
        is_source = isinstance(seq, Source)
    except NameError:
        is_source = False

    if is_source:
        return False

    # Avoid treating strings or bytes as sequences of interest
    if isinstance(seq, (str, bytes)):
        return False

    # Attempt to iterate over seq
    try:
        iterator = iter(seq)
    except TypeError:
        # seq is not iterable
        return False

    # Iterate and look for any FillRequest element
    for item in iterator:
        try:
            if isinstance(item, FillRequest):
                return True
        except NameError:
            # If FillRequest type not available, skip this item
            continue

    return False<|return|>

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (
            hasattr(obj, "fill") and callable(getattr(obj, "fill", None)) and
            hasattr(obj, "request") and callable(getattr(obj, "request", None))
        )
    except Exception:
        return False<|return|>

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return hasattr(obj, 'run') and callable(getattr(obj, 'run'))
    except Exception:
        return False<|return|>

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    if obj is None:
        return False
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
