        cur_level of -1 indicates unlimited depth.
        """
        # If level limits to 0, do not recurse further
        if cur_level == 0:
            return {}

        out = {}
        for key, val in d1_local.items():
            if key not in d2_local:
                # Key absent in d2: include entire val
                out[key] = val
                continue

            # Key exists in both: evaluate based on type
            val2 = d2_local[key]
            if isinstance(val, dict) and isinstance(val2, dict):
                # Both are dicts -> recurse if level > 1 or unlimited
                if cur_level == -1 or cur_level > 1:
                    sub = _diff(val, val2, cur_level - 1 if cur_level > 0 else -1)
                    if sub:
                        out[key] = sub
                else:
                    # At level 1, treat dicts as differing values
                    if cur_level == -1 or cur_level == 1:
                        out[key] = val
            else:
                # Non-dict values
                if val != val2:
                    out[key] = val
        return out

    # If the level is -1, treat as unlimited
    effective_level = level if level != -1 else -1
    # Compute difference
    diff_result = _diff(d1, d2, effective_level)

    # If the diff is empty, return an empty dict
    return diff_result if diff_result else {}
<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    try:
        import re
    except Exception as exc:  # pragma: no cover - unlikely to fail
        raise ValueError("The re module is required for label validation.") from exc

    # Common regex patterns for Kubernetes-style labels.
    # These are illustrative; they can be adjusted to match the real patterns needed.
    _label_key_regex = re.compile(r"^[A-Za-z0-9]([-A-Za-z0-9_.]{0,127})?[A-Za-z0-9]$")
    _label_value_regex = re.compile(r"^[A-Za-z0-9]([-A-Za-z0-9_.]{0,63})?[A-Za-z0-9]?$")

    errors = []

    def _add_error(key, message):
        errors.append({str(key): message})

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            _add_error(key, "expected string or bytes-like object")
        else:
            key_str = key if isinstance(key, str) else key.decode("utf-8", errors="ignore")
            if not _label_key_regex.match(key_str):
                _add_error(key, f"Label key '{key_str}' does not match the regex [...]")

        # Validate value(s)
        # Allow list of values or single value
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    _add_error(v, "expected string or bytes-like object")
                    continue
                v_str = v if isinstance(v, str) else v.decode("utf-8", errors="ignore")
                if not _label_value_regex.match(v_str):
                    _add_error(v, f"Label value '{v_str}' does not match the regex [...]")
        else:
            # Single value case
            if not isinstance(value, (str, bytes)):
                _add_error(value, "expected string or bytes-like object")
            else:
                v_str = value if isinstance(value, str) else value.decode("utf-8", errors="ignore")
                if not _label_value_regex.match(v_str):
                    _add_error(key, f"Label value '{v_str}' does not match the regex [...]")

    if errors:
        # The ValidationError is assumed to be defined elsewhere in the code base.
        # It should accept a list of error dictionaries via a `messages` attribute.
        try:
            ValidationError = globals()["ValidationError"]
        except KeyError:
            # Fallback generic exception if ValidationError is not available
            raise Exception(errors) from None
        raise ValidationError(messages=errors) from None

    return None<|return|>

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        # Ensure the value is a non-empty string
        if not isinstance(value, str):
            raise ValidationError("Value must be a string.")
        if value == "":
            raise ValidationError("Value cannot be empty.")
        # Simple alphanumeric check without using regular expressions
        if not value.isalnum():
            raise ValidationError("Value contains invalid characters; only letters and digits are allowed.")
    except Exception as exc:
        # Re-raise any validation-related errors as ValidationError
        raise ValidationError(f"Validation error: {exc}") from exc<|return|>

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list using a
    nested Kubernetes response and an observation schema.

    Parameters
    ----------
    last_applied_manifest : list
        Partial ``last_applied_manifest`` being updated. Each element is
        expected to be a dict.
    observer_schema : list
        Schema describing the fields of interest. Each element may contain:
        - ``path`` : dot separated string indicating the path within the
          manifest to update (e.g. ``metadata.labels``).
        - ``sub_schema`` : Optional list describing nested objects (used
          recursively).
    response : list
        Partial Kubernetes API response, corresponding structure to
        ``observer_schema``.

    Returns
    -------
    list
        Updated ``last_applied_manifest`` (same object as passed in).

    Notes
    -----
    - If a field defined in ``observer_schema`` is absent in
      ``last_applied_manifest`` but present in ``response``, it is added.
    - The function handles nested dictionaries and lists by recursively
      processing any ``sub_schema`` entries.
    - Missing fields in the response are ignored; invalid types raise a
      ValueError with a descriptive message.
    """
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Helper to retrieve value from a dictionary given a dot‑separated path
    def _get_from_response(resp_dict, path_parts):
        current = resp_dict
        for part in path_parts:
            if isinstance(current, dict) and part in current:
                current = current[part]
            else:
                return None, False
        return current, True

    # Helper to set value in a dictionary given a dot‑separated path
    def _set_in_manifest(man_dict, path_parts, value):
        current = man_dict
        for part in path_parts[:-1]:
            # Create nested dict if missing or not a dict
            if part not in current or not isinstance(current[part], dict):
                current[part] = {}
            current = current[part]
        # Set the leaf value
        current[path_parts[-1]] = value

    # Iterate over the top level of the response and update corresponding
    # entries in the manifest. If observer_schema defines sub‑schemas for
    # nested objects, we recurse into them.
    for i, schema_item in enumerate(observer_schema):
        if not isinstance(schema_item, dict):
            # Skip malformed schema entries
            continue

        path = schema_item.get("path")
        sub_schema = schema_item.get("sub_schema")

        if path is None:
            continue

        path_parts = path.split(".")

        # Retrieve the value from the response
        # The response may be a list of dicts; we assume all schema items
        # correspond to the first dict in the list (or a single dict).
        if not response:
            continue
        resp_obj = response[0] if isinstance(response, list) else response

        value, found = _get_from_response(resp_obj, path_parts)
        if not found:
            # No value in response; nothing to update
            continue

        # If there's a sub‑schema, the value must be a dict/list and we
        # recurse into each element.
        if sub_schema:
            if isinstance(value, dict):
                # Recursively update this dict
                if i < len(last_applied_manifest) and isinstance(last_applied_manifest[i], dict):
                    nested_resp = [value]
                    nested_manifest = [last_applied_manifest[i]]
                else:
                    # Initialize nested dict if missing
                    nested_manifest = [{}]
                    nested_resp = [value]
                update_last_applied_manifest_list_from_resp(
                    nested_manifest, sub_schema, nested_resp
                )
                # Place updated nested dict back
                if i < len(last_applied_manifest):
                    last_applied_manifest[i] = nested_manifest[0]
                else:
                    last_applied_manifest.append(nested_manifest[0])
            elif isinstance(value, list):
                # For list of objects, map each element to the corresponding
                # manifest element (creating new ones if needed)
                if i < len(last_applied_manifest) and isinstance(last_applied_manifest[i], list):
                    nested_manifest = last_applied_manifest[i]
                else:
                    nested_manifest = []
                # Ensure manifest list is long enough
                while len(nested_manifest) < len(value):
                    nested_manifest.append({})
                for j, item_val in enumerate(value):
                    if isinstance(item_val, dict):
                        update_last_applied_manifest_list_from_resp(
                            nested_manifest, sub_schema, [item_val]
                        )
                # Write back
                if i < len(last_applied_manifest):
                    last_applied_manifest[i] = nested_manifest
                else:
                    last_applied_manifest.append(nested_manifest)
            else:
                # Primitive value with sub_schema is inconsistent; skip
                continue
        else:
            # Direct leaf value: set in the corresponding manifest element.
            if i < len(last_applied_manifest) and isinstance(last_applied_manifest[i], dict):
                _set_in_manifest(last_applied_manifest[i], path_parts, value)
            else:
                # If no manifest dict exists for this index, create one
                new_dict = {}
                _set_in_manifest(new_dict, path_parts, value)
                if i < len(last_applied_manifest):
                    last_applied_manifest[i] = new_dict
                else:
                    last_applied_manifest.append(new_dict)

    return last_applied_manifest<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Update ``last_applied_manifest`` in-place by filling in fields that are not
    already present, using the structure defined by ``observer_schema`` and the
    values from ``response``.  The function descends recursively into nested
    dictionaries.  ``observer_schema`` is a mapping from field names to either a
    sub‑schema (dict) or a list of sub‑schemata.  The corresponding function
    :func:`update_last_applied_manifest_list_from_resp` is responsible for
    handling list‑type fields.

    Args:
        last_applied_manifest (dict): Partial last_applied_manifest being updated.
        observer_schema (dict): Schema describing the fields that should be
            present in ``last_applied_manifest``.
        response (dict): Partial response from the Kubernetes API.

    Raises:
        KeyError: If an observed field is not present in ``response``.
        TypeError: If the type of the observed field in ``response`` does not
            match the expected type defined by ``observer_schema``.
    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, sub_schema in observer_schema.items():
        # Ensure key exists in the Kubernetes response
        if key not in response:
            raise KeyError(f"Observed key '{key}' missing from response")

        # If the key hasn't been set yet, initialise it
        if key not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                # Nested dictionary: start with an empty dict and recurse
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            elif isinstance(sub_schema, list):
                # Delegates to the list‑handling helper
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest, key, sub_schema, response[key]
                )
            else:
                # Primitive value: copy directly
                last_applied_manifest[key] = response[key]
        else:
            # Key already present; ensure nested structures are also updated
            if isinstance(sub_schema, dict):
                if not isinstance(response[key], dict):
                    raise TypeError(
                        f"Expected dict for field '{key}' in response, "
                        f"got {type(response[key]).__name__}"
                    )
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            elif isinstance(sub_schema, list):
                # For lists we rely on the dedicated helper to keep consistency
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest, key, sub_schema, response[key]
                )
    # No return; modification is in-place.<|return|>

def status_str(self, prefix=''):
        """Return string representation of validation log, with optional prefix."""
        # Validate prefix type
        if not isinstance(prefix, str):
            raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
        # Try to locate the log entries on the instance
        entries = None
        for attr in ('records', '_records', 'log', '_log', 'entries', '_entries'):
            if hasattr(self, attr):
                entries = getattr(self, attr)
                break
        # If no log attribute is found, return an empty string
        if entries is None:
            return ''
        # Ensure entries is iterable
        try:
            iter(entries)
        except TypeError as exc:
            raise ValueError(f"Log entries must be iterable, got {type(entries).__name__}") from exc
        # Build lines
        lines = []
        for rec in entries:
            # Rec could be a dict with 'message', a tuple, or a plain string.
            if isinstance(rec, dict):
                msg = rec.get('message', str(rec))
            elif isinstance(rec, (list, tuple)) and rec:
                # Prefer first element if it's string
                msg = rec[0] if isinstance(rec[0], str) else str(rec)
            else:
                msg = str(rec)
            if prefix:
                lines.append(f"{prefix}{msg}")
            else:
                lines.append(msg)
        return "\n".join(lines)<|return|>

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type checking for the inventory argument
        if not isinstance(inventory, dict):
            raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

        # Attempt to extract specification version from the 'type' key if requested
        if extract_spec_version:
            type_value = inventory.get("type")
            if isinstance(type_value, str):
                # Known mapping from type to spec version
                type_to_version = {
                    "inventory_v1": "1",
                    "inventory_v2": "2",
                    "inventory_v3": "3",
                }
                # Update the instance's spec_version only if we have a mapping
                if type_value in type_to_version:
                    self.spec_version = type_to_version[type_value]
            # If type_value is missing or not a string, silently fall back to existing spec_version

        # Ensure we have some spec version to work with (fallback to self.spec_version if unset)
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise ValueError("Specification version is not set and could not be inferred.")

        # Begin validation of required inventory structure
        required_root_keys = ["items"]
        missing_root_keys = [key for key in required_root_keys if key not in inventory]
        if missing_root_keys:
            raise ValueError(f"Missing required root keys in inventory: {missing_root_keys}")

        items = inventory["items"]
        if not isinstance(items, list):
            raise TypeError(f"'items' must be a list, got {type(items).__name__}")

        # Define schema for inventory items based on spec version
        # For the purposes of this method, we enforce a simple set of fields
        spec_schemas = {
            "1": {"required_fields": ["id", "value"]},
            "2": {"required_fields": ["id", "value", "quantity"]},
            "3": {"required_fields": ["id", "value", "quantity", "price"]},
        }

        schema = spec_schemas.get(str(spec_version))
        if schema is None:
            raise ValueError(f"Unsupported specification version: {spec_version}")

        # Validate each item
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise TypeError(f"Item at index {idx} must be a dict, got {type(item).__name__}")

            missing_fields = [
                field for field in schema["required_fields"] if field not in item
            ]
            if missing_fields:
                raise ValueError(
                    f"Item at index {idx} is missing required fields: {missing_fields}"
                )

            # Optional: Add type checks for specific fields
            if not isinstance(item["id"], (str, int)):
                raise TypeError(
                    f"Item at index {idx} has 'id' of unsupported type: {type(item['id']).__name__}"
                )
            if not isinstance(item["value"], (int, float)):
                raise TypeError(
                    f"Item at index {idx} has 'value' of unsupported type: {type(item['value']).__name__}"
                )
            if "quantity" in schema["required_fields"] and not isinstance(item["quantity"], int):
                raise TypeError(
                    f"Item at index {idx} has 'quantity' of unsupported type: {type(item['quantity']).__name__}"
                )
            if "price" in schema["required_fields"] and not isinstance(item["price"], (int, float)):
                raise TypeError(
                    f"Item at index {idx} has 'price' of unsupported type: {type(item['price']).__name__}"
                )

        # If all checks pass, return True to indicate successful validation
        return True
<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure 'prior' is an instance of the same class as self
        if not isinstance(prior, type(self)):
            raise TypeError(f"Expected InventoryValidator instance, got {type(prior).__name__}")

        def _get_version(obj):
            """Retrieve a version identifier from an InventoryValidator-like object."""
            # Common attribute name
            try:
                return getattr(obj, "version")
            except AttributeError:
                pass

            # Check for 'inventory' dict containing 'version'
            inv = getattr(obj, "inventory", None)
            if isinstance(inv, dict):
                return inv.get("version")

            # Fall back to a method get_version()
            if callable(getattr(obj, "get_version", None)):
                return obj.get_version()

            return None

        self_version = _get_version(self)
        prior_version = _get_version(prior)

        if self_version is None or prior_version is None:
            raise ValueError("Version information missing in one of the inventories.")

        # Try numeric comparison; fall back to string comparison if conversion fails
        try:
            self_num = float(self_version)
            prior_num = float(prior_version)
        except (TypeError, ValueError):
            self_num, prior_num = self_version, prior_version

        if prior_num >= self_num:
            raise ValueError(
                f"Prior version {prior_num!r} is not older than current version {self_num!r}."
            )

        return True<|return|>

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("`inventory` must be a dictionary")
    if not isinstance(version, (str, int)):
        raise TypeError("`version` must be a str or int")

    result = {}

    # Helper to add entries from a mapping of logical_path -> iterables
    def _add_from_mapping(mapping):
        if not isinstance(mapping, dict):
            return
        for lp, files in mapping.items():
            try:
                # Files could be a list, set, tuple, or a single string
                if isinstance(files, (list, set, tuple)):
                    files_set = set(files)
                else:
                    files_set = {files}
            except Exception:
                # Skip entries that cannot be interpreted as iterable
                continue
            if lp in result:
                result[lp].update(files_set)
            else:
                result[lp] = files_set

    # Get mapping for the requested version
    mapping = inventory.get(version)
    if mapping is not None:
        # The mapping might be the direct dict or wrapped inside a 'state' key
        if isinstance(mapping, dict):
            # Check if it directly maps logical_path -> files
            # Use heuristic: if any value is a string or list, treat as mapping
            try:
                sample_val = next(iter(mapping.values()))
                if isinstance(sample_val, (list, set, tuple, str)):
                    _add_from_mapping(mapping)
                    return result
            except Exception:
                pass
            # If not directly mapping, check for 'state'
            state = mapping.get('state')
            if isinstance(state, dict):
                _add_from_mapping(state)
                return result

    # If we reach here, try to find a 'state' mapping under the version key
    state_mapping = inventory.get(version, {}).get('state')
    if isinstance(state_mapping, dict):
        _add_from_mapping(state_mapping)

    # If still empty, try to use the whole inventory as the mapping
    if not result:
        try:
            _add_from_mapping(inventory)
        except Exception:
            pass

    # Include duplicates from later versions
    try:
        # Sort keys so that we can compute "later" versions
        sorted_versions = sorted(inventory.keys(), key=lambda x: str(x))
    except Exception:
        sorted_versions = []

    if sorted_versions:
        try:
            idx = sorted_versions.index(version)
            later_versions = sorted_versions[idx + 1 :]
        except ValueError:
            later_versions = []

        for lv in later_versions:
            later_mapping = inventory.get(lv)
            if not isinstance(later_mapping, dict):
                continue
            # Attempt both direct and state-wrapped form
            if isinstance(later_mapping.get("state"), dict):
                _add_from_mapping(later_mapping["state"])
            else:
                _add_from_mapping(later_mapping)

    # Ensure every entry is a set (could happen if earlier mapping failed)
    for lp in list(result.keys()):
        if not isinstance(result[lp], set):
            try:
                result[lp] = set(result[lp])
            except Exception:
                # Fallback to empty set to avoid returning non-set
                result[lp] = set()

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Validate input types
        if not isinstance(fixity, dict):
            raise ValueError("fixity must be a dictionary where keys are file names and values are checksums.")
        if not isinstance(manifest_files, (set, list, tuple)):
            raise ValueError("manifest_files must be a set, list, or tuple of file names.")
        manifest_set = set(manifest_files)

        # Validate each entry in the fixity block
        for filename, checksum in fixity.items():
            if filename not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{filename}'.")
            if not isinstance(checksum, str):
                raise ValueError(f"Checksum for file '{filename}' must be a string, got {type(checksum).__name__}.")
        # If no problems are found, validation passes silently (returns None).<|return|>

def files_list(path):
    import os
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a string, bytes, or PathLike object")
    try:
        with os.scandir(path) as it:
            return [entry.name for entry in it if entry.is_file()]
    except OSError as e:
        raise FileNotFoundError(f"Cannot access directory at {path}") from e<|return|>

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not isinstance(pubdate_xpaths, (list, tuple)):
        return None
    for xpath in pubdate_xpaths:
        try:
            results = node.xpath(xpath)
            if results:
                match = results[0]
                # If it's an lxml element, get its text content; otherwise cast to string
                if hasattr(match, "text_content"):
                    return match.text_content().strip()
                return str(match).strip()
        except Exception:
            # Ignore malformed xpaths or evaluation errors and continue to next
            continue
    return None<|return|>

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    The representation is built recursively for built‑in collections
    (dict, list, tuple, set) and for user objects that expose a __dict__.
    If the ``debug`` flag is True, any exception that occurs while
    constructing the representation is caught and reported in the
    output; otherwise the exception is re‑raised.
    """
    def _recurse(obj, level, seen):
        space = " " * level
        if id(obj) in seen:
            return f"<recursion of {type(obj).__name__} id={id(obj)}>"

        seen.add(id(obj))

        try:
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    items.append(f"{repr(k)}: {_recurse(v, level + 2, seen)}")
                return "{\n" + ",\n".join(space + "  " + item for item in items) + f"\n{space}}}"
            if isinstance(obj, list):
                items = [_recurse(v, level + 2, seen) for v in obj]
                return "[\n" + ",\n".join(space + "  " + item for item in items) + f"\n{space}]"
            if isinstance(obj, tuple):
                items = [_recurse(v, level + 2, seen) for v in obj]
                return "(\n" + ",\n".join(space + "  " + item for item in items) + f"\n{space})"
            if isinstance(obj, set):
                items = [_recurse(v, level + 2, seen) for v in obj]
                return "{\n" + ",\n".join(space + "  " + item for item in items) + f"\n{space}}}"
            if hasattr(obj, "__dict__"):
                attrs = vars(obj)
                items = [f"{k}={_recurse(v, level + 2, seen)}" for k, v in attrs.items()]
                return f"{obj.__class__.__name__}(\n" + ",\n".join(space + "  " + item for item in items) + f"\n{space})"
            # Fallback to native representation
            return repr(obj)
        finally:
            seen.remove(id(obj))

    try:
        return _recurse(self, indent, set())
    except Exception as exc:
        if debug:
            return f"<PrettyError: {exc}>"
        # Preserve original exception for debugging
        raise<|endoftext|>

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    Raises:
        ValueError: If any argument is of an incorrect type or invalid value.
    """
    # Basic validation of inputs
    if not isinstance(user, str) or not user.strip():
        raise ValueError("user must be a non-empty string")
    if not isinstance(etcd_host, str) or not etcd_host.strip():
        raise ValueError("etcd_host must be a non-empty string")
    if not isinstance(etcd_port, int) or etcd_port <= 0 or etcd_port > 65535:
