def get_versions():
    """Get version information or return default if unable to do so."""
    import sys
    try:
        import importlib.metadata as metadata
        # Retrieve Python version
        python_version = sys.version

        # Gather installed package versions
        package_versions = {}
        for dist in metadata.distributions():
            # Some distributions may not have 'Name' metadata; use dist.metadata
            name = dist.metadata.get("Name") or dist.metadata.get("name") or dist.metadata.get("distribution")
            if not name:
                # Fall back to distribution name
                name = dist.metadata.get("Name") or dist.metadata.get("name") or dist.metadata.get("distribution")
            if name:
                package_versions[name] = dist.version

        return {"python": python_version, "packages": package_versions}
    except Exception:
        # If any step fails, return a minimal default
        return {"python": sys.version, "packages": {}}
<|return|>

