def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    # Normalize command input
    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, (str, bytes)):
        cmd = [commands] + list(args if args is not None else [])
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands) + list(args if args is not None else [])
    else:
        raise TypeError("commands must be a str or a list/tuple of strings")

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=None if hide_stderr else subprocess.PIPE,
            text=True,
            check=False,
        )

        # Verbose output
        if verbose:
            print("Command:", " ".join(shlex.quote(c) for c in cmd))
            if result.stdout:
                print("STDOUT:\n", result.stdout.rstrip())
            if not hide_stderr and result.stderr:
                print("STDERR:\n", result.stderr.rstrip())

        # Raise if non-zero exit, include stderr if available
        if result.returncode != 0:
            err_msg = f"Command {' '.join(cmd)} failed with exit code {result.returncode}"
            if not hide_stderr and result.stderr:
                err_msg += f": {result.stderr.strip()}"
            raise subprocess.CalledProcessError(
                result.returncode,
                cmd,
                output=result.stdout,
                stderr=result.stderr if not hide_stderr else None,
            )

        return result

    except FileNotFoundError as nf_err:
        raise subprocess.CalledProcessError(-1, cmd, output=None, stderr=str(nf_err)) from nf_err
    except Exception:
        raise
<|return|>

