def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Ensure the storage root exists and is a dict-like iterable
        if not hasattr(self, "storage_root"):
            if show_warnings:
                print("Warning: No storage_root attribute found.")
            return 0, 0

        storage_root = self.storage_root
        if not isinstance(storage_root, dict):
            if show_warnings:
                print("Warning: storage_root is not a dictionary; cannot validate.")
            return 0, 0

        num_objects = 0
        good_objects = 0

        import hashlib
        import json

        for obj_id, obj in storage_root.items():
            num_objects += 1
            is_valid = True
            try:
                # Basic validation: check that the object is a dict
                if not isinstance(obj, dict):
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj_id} is not a dict.")
                else:
                    # Validate required fields if requested
                    if validate_objects:
                        # Example: require 'data' field
                        if 'data' not in obj:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: Object {obj_id} missing 'data' field.")
                        # Example: require 'size' greater than zero
                        if 'size' in obj:
                            try:
                                if int(obj['size']) <= 0:
                                    is_valid = False
                                    if show_warnings:
                                        print(f"Warning: Object {obj_id} has non-positive size.")
                            except (TypeError, ValueError):
                                is_valid = False
                                if show_warnings:
                                    print(f"Warning: Object {obj_id} has invalid size type.")
                    # Digest check
                    if check_digests:
                        if 'digest' not in obj or 'data' not in obj:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: Object {obj_id} missing 'digest' or 'data' for digest check.")
                        else:
                            try:
                                # Assume data is json-serializable; compute SHA256
                                data_bytes = json.dumps(obj['data'], sort_keys=True).encode('utf-8')
                                computed_digest = hashlib.sha256(data_bytes).hexdigest()
                                if obj['digest'] != computed_digest:
                                    is_valid = False
                                    if show_warnings:
                                        print(f"Warning: Object {obj_id} digest mismatch.")
                            except Exception as e:
                                is_valid = False
                                if show_warnings:
                                    print(f"Warning: Object {obj_id} failed digest computation: {e}")
                # Store validation result if present
                if is_valid:
                    good_objects += 1
                else:
                    # Cache the validation result if possible
                    if isinstance(obj, dict):
                        obj.setdefault('valid', False)
            except Exception as e:
                # Catch unexpected errors per object to continue processing others
                if show_warnings:
                    print(f"Warning: Unexpected error while validating object {obj_id}: {e}")
                continue

        return num_objects, good_objects<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    width = len(version)
    try:
        num = int(version)
    except Exception:
        raise ValueError("unable to parse version")
    next_num = num + 1
    return str(next_num).rjust(width, '0')<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    try:
        def merge_mapping(val1, val2):
            """
            Recursively merge two MappingNode values. The mapping nodes contain a tag and
            a list of scalar-node/key tuples. The merged mapping preserves the order of keys
            from the first mapping, while appending new keys from the second.
            """
            tag = val1.tag if isinstance(val1, type(val2)) else val2.tag
            # Convert list of tuples to ordered dict for easier merging
            def to_dict(mapping):
                d = {}
                for k_node, v_node in mapping.value:
                    d[k_node.value] = (k_node, v_node)
                return d

            dict1 = to_dict(val1)
            dict2 = to_dict(val2)

            merged_items = []
            used_keys = set()

            # Order keys from dict1
            for k_val, (k_node, v_node) in dict1.items():
                if k_val in dict2:
                    # Merge if both are mapping nodes
                    v2_node = dict2[k_val][1]
                    if isinstance(v_node, type(v2_node)) and getattr(v_node, 'tag', None) == 'tag:yaml.org,2002:map':
                        merged_val = merge_mapping(v_node, v2_node)
                    else:
                        merged_val = v2_node
                    merged_items.append((k_node, merged_val))
                    used_keys.add(k_val)
                else:
                    merged_items.append((k_node, v_node))
                    used_keys.add(k_val)

            # Add remaining keys from dict2 that were not in dict1
            for k_val, (k_node, v_node) in dict2.items():
                if k_val not in used_keys:
                    merged_items.append((k_node, v_node))
                    used_keys.add(k_val)

            return type(val1)(tag=tag, value=merged_items)

        result_dict = {}
        key_order = []

        for key_node, val_node in nodes:
            if not hasattr(key_node, 'value'):
                raise ValueError("Key node does not contain a 'value' attribute")
            key = key_node.value
            if key in result_dict:
                existing_val = result_dict[key]
                # If both values are MappingNode-like, merge them
                if getattr(existing_val, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(val_node, 'tag', None) == 'tag:yaml.org,2002:map':
                    merged_val = merge_mapping(existing_val, val_node)
                else:
                    merged_val = val_node  # last value wins
                result_dict[key] = (key_node, merged_val)
            else:
                result_dict[key] = (key_node, val_node)
                key_order.append(key)

        # Construct the final list preserving key order
        merged_list = [result_dict[k] for k in key_order]
        return merged_list

    except Exception as exc:
        raise RuntimeError(f"Error during deep merging of nodes: {exc}") from exc
<|return|>

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments
    and return them as an argparse.Namespace instance.
    '''
    import argparse

    # Initialize the parser
    parser = argparse.ArgumentParser()

    # Normalise the input arguments to a list of strings
    args = []
    for arg in arguments:
        if isinstance(arg, str):
            args.append(arg)
        elif isinstance(arg, (bytes, bytearray)):
            # Decode bytes to str using UTF-8, fall back to latin1 if needed
            try:
                args.append(arg.decode('utf-8'))
            except Exception:
                args.append(arg.decode('latin1'))
        else:
            try:
                args.append(str(arg))
            except Exception as e:
                raise TypeError(f"Argument {arg!r} cannot be converted to a string") from e

    # Parse the arguments and return the resulting Namespace
    try:
        return parser.parse_args(args)
    except SystemExit as exc:
        # argparse calls sys.exit() on errors, which raises SystemExit.
        # Convert this into a runtime error to avoid terminating the caller.
        raise RuntimeError("Argument parsing failed.") from exc<|return|>

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        import argparse
        if not isinstance(parser, argparse.ArgumentParser):
            raise TypeError('parser must be an argparse.ArgumentParser instance')
        flags = []
        for action in getattr(parser, '_actions', []):
            # action.option_strings may be empty for positional arguments
            for opt in getattr(action, 'option_strings', []):
                if opt:  # skip empty strings
                    flags.append(opt)
        return ' '.join(flags)
    except Exception as e:
        raise ValueError(f'Error extracting flags: {e}') from e<|return|>

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    # Import inside the function to avoid adding a module level import
    try:
        import argparse
    except Exception as exc:
        raise RuntimeError(f"Failed to import argparse: {exc}") from exc

    try:
        # Create the main parser with a brief description
        parser = argparse.ArgumentParser(
            description="Top-level command line interface"
        )

        # Add subparsers; the caller can add commands to this object
        subparsers = parser.add_subparsers(dest='command')
        return (parser, subparsers)
    except Exception as exc:
        raise RuntimeError(f"Failed to create parsers: {exc}") from exc<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Expected an iterable of dictionaries, got None")
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("dicts must be an iterable of dictionaries") from exc

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Item {idx} in dicts is not a dict (found {type(d).__name__})")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as exc:
                    raise TypeError(f"Cannot sum values for key {key!r}: {exc}") from exc
            else:
                result[key] = value
    return result<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.

    The function supports placeholder syntax of the form ``{key}`` where ``key``
    can be either a dictionary key or an integer index into a list/tuple.
    If a placeholder cannot be resolved, it is left unchanged.

    Parameters
    ----------
    url : str
        The URL containing zero or more ``{placeholder}`` items.
    url_args : Mapping or Sequence
        Values used to fill the placeholders.  If a dict is passed, the
        placeholder name must match a key.  If a sequence is passed,
        integer placeholders refer to the corresponding index.

    Returns
    -------
    str
        The URL with placeholders replaced by the respective values.
        If a placeholder could not be resolved, it remains unchanged.

    Raises
    ------
    TypeError
        If ``url`` is not a string or if ``url_args`` is neither a mapping
        nor a sequence.
    """
    import re
    if not isinstance(url, str):
        raise TypeError("url must be a string, got %r" % (type(url).__name__,))
    if url_args is None:
        return url
    # Determine the type of url_args
    if isinstance(url_args, dict):
        def repl(match):
            key = match.group(1)
            if key in url_args:
                return str(url_args[key])
            return match.group(0)
    elif isinstance(url_args, (list, tuple)):
        def repl(match):
            idx_str = match.group(1)
            try:
                idx = int(idx_str)
            except ValueError:
                return match.group(0)
            if 0 <= idx < len(url_args):
                return str(url_args[idx])
            return match.group(0)
    else:
        raise TypeError(
            "url_args must be a mapping or a sequence, got %r"
            % (type(url_args).__name__,)
        )

    # Replace all occurrences of {placeholder}
    pattern = re.compile(r"{([^{}]+)}")
    return pattern.sub(repl, url)<|return|>

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        # Ensure the parser has the expected structure
        if not hasattr(parser, "_actions"):
            raise TypeError("Expected an argparse.ArgumentParser instance.")
        flags = []
        for action in parser._actions:
            # action.option_strings contains all flags for this action (empty for positional)
            for opt in action.option_strings:
                if opt not in flags:
                    flags.append(opt)
        return " ".join(flags)
    except Exception:
        # If anything goes wrong, return an empty string as a safe fallback
        return ""<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("all alphabet elements must be strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique elements")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two unique symbols")

    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")

    base = len(alphabet)
    digits = []

    # Special case for 0
    if number == 0:
        digits.append(alphabet[0])
    else:
        temp = number
        while temp > 0:
            digits.append(alphabet[temp % base])
            temp //= base
        digits.reverse()

    result = ''.join(digits)

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result
<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate types
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key name")

    def _recursive_replace(d):
        """Recursively replace key values in nested dictionaries and lists."""
        if not isinstance(d, dict):
            return
        for key, val in list(d.items()):
            # Replace the value if the key matches register_value
            if key == register_value:
                d[key] = register_number
            # Recurse into nested dicts or lists
            if isinstance(val, dict):
                _recursive_replace(val)
            elif isinstance(val, list):
                for item in val:
                    if isinstance(item, dict):
                        _recursive_replace(item)

    try:
        _recursive_replace(flow_params)
    except Exception as e:
        # Log or re-raise a more specific error if needed
        raise RuntimeError(f"Error during register replacement: {e}") from e

    return flow_params<|return|>

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    try:
        if value is None:
            return None
        if not isinstance(value, str):
            raise TypeError("value must be a string")
        if not isinstance(arg, str):
            raise TypeError("arg must be a string")
        return value.replace('.', arg)
    except Exception as exc:
        # Re-raise as a ValueError with context
        raise ValueError(f"Failed to replace dots: {exc}") from exc<|return|>

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {cls!r}")  # pragma: no cover
    seen = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        for sub in parent.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen

<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of alphabet
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two unique digits.")
    # Create a mapping from character to its numeric value
    digit_map = {ch: idx for idx, ch in enumerate(alphabet)}
    if len(digit_map) != base:
        raise ValueError("Alphabet characters must be unique.")
    # Validate input string
    if not string:
        raise ValueError("Input string cannot be empty.")
    result = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"Character '{ch}' not in alphabet.")
        result = result * base + digit_map[ch]
    return result<|return|>

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() returns a tuple-like object with sysname attribute on POSIX systems.
        return getattr(os, "uname", lambda: None)().sysname == "Darwin"
    except Exception:
        # os.uname may not be available on non-POSIX platforms (e.g., Windows).
        # Fallback to checking sys.platform.
        try:
            import sys
            return sys.platform.startswith("darwin")
        except Exception:
            return False<|return|>

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        _, ext = os.path.splitext(filename.lower())
        supported_extensions = {'.txt', '.csv', '.log'}
        return ext in supported_extensions
    except Exception:
        return False<|return|>

