    :return: True if the host resolves to a loopback address, otherwise False
    """
    if not isinstance(host, str) or not host.strip():
        # Empty or non-string values are not considered local
        return False

    try:
        # Resolve all address info for the given host (no port needed)
        addrinfo_list = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        # Name resolution failed – cannot be local
        return False

    for family, _, _, _, sockaddr in addrinfo_list:
        if family == socket.AF_INET:
            # IPv4 loopback address
            if sockaddr[0] == "127.0.0.1":
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address
            if sockaddr[0] == "::1":
                return True

    # No loopback addresses found
    return False<|return|>

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Basic type validation
    if not isinstance(config_filename, str):
        raise TypeError('"config_filename" must be a string')
    if not isinstance(rendered_config, str):
        raise TypeError('"rendered_config" must be a string')
    if not isinstance(mode, int):
        raise TypeError('"mode" must be an integer')
    if not isinstance(overwrite, bool):
        raise TypeError('"overwrite" must be a boolean')

    # Resolve absolute path and ensure directory exists
    abs_path = os.path.abspath(config_filename)
    dir_name = os.path.dirname(abs_path)
    if dir_name and not os.path.isdir(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as exc:
            raise OSError(f'Failed to create directories for {abs_path}: {exc}') from exc

    # Abort if file exists and we are not allowed to overwrite
    if os.path.exists(abs_path) and not overwrite:
        raise FileExistsError(f'File {abs_path} already exists and overwrite is False')

    # Write the rendered configuration to the file
    try:
        with open(abs_path, 'w', encoding='utf-8') as cfg_file:
            cfg_file.write(rendered_config)
        os.chmod(abs_path, mode)
    except Exception as exc:
        raise IOError(f'Unable to write configuration to {abs_path}: {exc}') from exc

    return True<|return|>

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name
    and an optional default value. If the variable is not defined
    in environment and no default value is provided, an error is raised.
    """
    # Determine name and default from various possible matcher formats
    if isinstance(matcher, str):
        var_name = matcher
        default = None
    elif isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher tuple/list must contain at least the variable name")
        var_name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise TypeError(
            "Matcher must be a string or a tuple/list containing the variable name"
        )

    # Attempt to fetch the environment variable
    try:
        value = os.getenv(var_name)
    except Exception as exc:
        raise RuntimeError(f"Failed to access environment variable '{var_name}': {exc}") from exc

    # If no value and no default, raise an error
    if value is None:
        if default is None:
            raise ValueError(
                f"Environment variable '{var_name}' is not set and no default value was provided"
            )
        return default

    return value
<|return|>

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: if the image_href is not a valid HTTP/HTTPS URL,
                       or if mandatory components are missing.
    """
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid image href '{image_href}'.") from exc

    if parsed.scheme not in ("http", "https"):
        raise ValueError(
            f"Unsupported scheme '{parsed.scheme}' in image href '{image_href}'. "
            "Only HTTP and HTTPS are supported."
        )

    if not parsed.netloc:
        raise ValueError(
            f"Missing network location (netloc) in image href '{image_href}'."
        )

    image_id = parsed.path.lstrip("/")
    if not image_id:
        raise ValueError(
            f"Missing image id (path component) in image href '{image_href}'."
        )

    use_ssl = parsed.scheme == "https"
    return image_id, parsed.netloc, use_ssl<|return|>

import ipaddress
def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except (ValueError, TypeError):
