def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Use the provided dumper or fall back to yaml.safe_dump
        if dumper is None:
            dumper = yaml.safe_dump

        # Dump the object; allow custom dumper signatures
        data = dumper(obj, default_flow_style=False)

        # If the dumper returned bytes (e.g. yaml.safe_dump in some pygments), decode them
        if isinstance(data, bytes):
            return data.decode("utf-8")
        # If the dumper returned None, treat it as an empty string
        if data is None:
            return ""
        # Otherwise return the string as is
        return data
    except Exception as exc:
        raise ValueError("Failed to dump object to string") from exc<|return|>

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape input
    if shape is None:
        raise ValueError("shape must not be None")
    try:
        shape_tuple = tuple(shape)
    except Exception as e:
        raise TypeError("shape must be a tuple or array-like of integers") from e
    if not isinstance(shape_tuple, tuple):
        raise TypeError("shape must be convertible to a tuple")
    if not all(isinstance(dim, int) for dim in shape_tuple):
        raise TypeError("all dimensions in shape must be integers")
    if not all(dim >= 0 for dim in shape_tuple):
        raise ValueError("all dimensions in shape must be non-negative")

    # Validate dtype input
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as e:
        raise TypeError("dtype must be a valid numpy dtype") from e

    # Create the array, handling potential runtime errors
    try:
        array = np.zeros(shape_tuple, dtype=dtype_obj)
    except Exception as e:
        raise RuntimeError(
            f"Failed to create array with shape={shape_tuple} "
            f"and dtype={dtype_obj}"
        ) from e

    return array<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return a tuple of:
      - dict mapping configuration filename to its parsed configuration (as a dict)
      - sequence of logging.LogRecord instances containing any parse errors
    """
    # Import modules locally to comply with no top-level imports rule
    import json
    import configparser
    import os
    import re
    import logging
    from json import JSONDecodeError
    from configparser import Error as ConfigParserError

    # Prepare return structures
    configs = {}
    error_records = []

    # Helper to create a LogRecord
    def _make_error_record(filename, exception):
        logger = logging.getLogger("config_loader")
        level = logging.ERROR
        msg = f"Error parsing '{filename}': {exception}"
        record = logging.LogRecord(name=logger.name, level=level,
                                   pathname=__file__, lineno=0,
                                   msg=msg, args=(), exc_info=None)
        return record

    # Helper to recursively resolve ${VAR} placeholders in strings within a nested dict/list
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_in_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_in_obj(item) for item in obj]
        elif isinstance(obj, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, obj)
        else:
            return obj

    # Helper to update config dictionary with overrides
    def _apply_overrides(config, overrides_dict):
        if not isinstance(overrides_dict, dict):
            raise TypeError("Override must be a dictionary")
        for key, value in overrides_dict.items():
            if isinstance(value, dict) and isinstance(config.get(key), dict):
                _apply_overrides(config[key], value)
            else:
                config[key] = value

    # Main processing loop
    for filename in config_filenames:
        if not isinstance(filename, str):
            record = _make_error_record(str(filename), TypeError("Filename must be a string"))
            error_records.append(record)
            continue

        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except FileNotFoundError as e:
            record = _make_error_record(filename, e)
            error_records.append(record)
            continue
        except Exception as e:
            record = _make_error_record(filename, e)
            error_records.append(record)
            continue

        # Determine file type and parse accordingly
        parsed_config = {}
        _, ext = os.path.splitext(filename.lower())
        try:
            if ext == '.json':
                parsed_config = json.loads(content)
                if not isinstance(parsed_config, dict):
                    raise ValueError("JSON root must be an object")
            elif ext in {'.ini', '.cfg', '.properties'}:
                parser = configparser.ConfigParser()
                parser.read_string(content)
                parsed_config = {s: dict(parser.items(s)) for s in parser.sections()}
                # Also capture defaults if any
                if parser.defaults():
                    parsed_config.setdefault('DEFAULT', {}).update(dict(parser.defaults()))
            else:
                # Fallback: simple key=value parsing
                parsed_config = {}
                for line in content.splitlines():
                    line = line.strip()
                    if not line or line.startswith(('#', ';')):
                        continue
                    if '=' not in line:
                        raise ValueError(f"Invalid line (no '='): {line}")
                    key, val = line.split('=', 1)
                    parsed_config[key.strip()] = val.strip()
        except (JSONDecodeError, ConfigParserError, ValueError) as e:
            record = _make_error_record(filename, e)
            error_records.append(record)
            # Continue to next file without adding incomplete config
            continue
        except Exception as e:
            record = _make_error_record(filename, e)
            error_records.append(record)
            continue

        # Apply overrides if any
        if overrides:
            try:
                for override_dict in overrides:
                    _apply_overrides(parsed_config, override_dict)
            except Exception as e:
                record = _make_error_record(filename, f"Overlaying overrides failed: {e}")
                error_records.append(record)
                continue

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed_config = _resolve_env_in_obj(parsed_config)
            except Exception as e:
                record = _make_error_record(filename, f"Env variable substitution failed: {e}")
                error_records.append(record)
                continue

        # Store the successfully parsed configuration
        configs[filename] = parsed_config

    return configs, error_records
<|return|>

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError(f"Unable to encode string to UTF-8: {exc}") from exc
    return obj<|return|>

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate that we received an iterable of strings
        try:
            raw_items = list(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings") from None

        for i, item in enumerate(raw_items):
            if not isinstance(item, str):
                raise TypeError(f"Bookmark value at index {i} must be a string, "
                                f"got {type(item).__name__}")

        # Attempt to construct the Bookmarks instance directly with the raw list.
        # Many Bookmark implementations support initializing from an iterable of raw
        # string values. If this fails, let the exception propagate.
        try:
            return cls(raw_items)
        except Exception as exc:
            raise ValueError(f"Failed to create a Bookmarks object from raw values: {exc}") from exc<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Helper to test whether an object is a container sequence.
    # We treat native sequences and any object that implements __len__ and __getitem__
    # as a sequence. This avoids converting things like generators or iterators.
    is_native_seq = isinstance(seq, (list, tuple, str, bytes, bytearray, memoryview))
    is_custom_seq = hasattr(seq, "__len__") and hasattr(seq, "__getitem__")

    if is_native_seq or is_custom_seq:
        # seq is already a sequence; return it unchanged.
        return seq, type(seq)

    # seq is not a sequence; try to iterate over it and build a list.
    try:
        if bufsize is None:
            # Consume entire iterable.
            new_seq = []
            for item in seq:
                new_seq.append(item)
        else:
            # Consume at most bufsize items.
            new_seq = []
            count = 0
            for item in seq:
                new_seq.append(item)
                count += 1
                if count >= bufsize:
                    break
    except Exception as exc:
        # Re-raise a more informative error about non-iterability.
        raise TypeError(
            f"Object of type {type(seq).__name__} is not iterable"
        ) from exc

    return new_seq, type(new_seq)<|return|>

