def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # ---------- helper to extract bins ----------
    def _extract_bins(h):
        """
        Returns a list of tuples: (low_edge, up_edge, content)
        """
        # ROOT-like histograms
        if hasattr(h, "GetNbinsX") and hasattr(h, "GetBinContent"):
            try:
                n = h.GetNbinsX()
                # try to get axis info
                axis = getattr(h, "GetXaxis", lambda: None)()
                if axis is None:
                    raise AttributeError
                bins = []
                for i in range(1, n + 1):
                    low = axis.GetBinLowEdge(i)
                    up = axis.GetBinUpEdge(i)
                    content = h.GetBinContent(i)
                    bins.append((low, up, content))
                return bins
            except Exception:
                pass  # fall through
        # Objects with a `.bins` attribute (list‑like)
        if hasattr(h, "bins"):
            return list(h.bins)
        # Iterable of (low, up, content) tuples
        if isinstance(h, (list, tuple)):
            # Basic validation
            for b in h:
                if not (isinstance(b, (list, tuple)) and len(b) == 3):
                    raise ValueError("Histogram iterable must contain tuples of (low, up, content)")
            return list(h)
        raise TypeError("Unsupported histogram type for conversion to graph")

    bins = _extract_bins(hist)

    # ---------- prepare make_value ----------
    if make_value is None:
        make_value_fn = lambda v: v
    elif callable(make_value):
        make_value_fn = make_value
    else:
        raise TypeError("make_value must be callable or None")

    # ---------- validate field_names ----------
    field_names = tuple(field_names)
    if not field_names or not isinstance(field_names, (list, tuple)):
        raise ValueError("field_names must be a non‑empty sequence")
    num_vals = len(field_names) - 1  # exclude x coordinate
    if num_vals < 0:
        raise ValueError("field_names must contain at least an 'x' field")

    # ---------- build graph ----------
    graph = {name: [] for name in field_names}
    for low, up, content in bins:
        try:
            val = make_value_fn(content)
        except Exception as exc:
            raise ValueError(f"make_value function raised an error for content {content!r}: {exc}") from exc

        # normalize val to a sequence
        if isinstance(val, (int, float)):
            if num_vals == 1:
                val_seq = (val,)
            else:
                raise ValueError(f"make_value returned a scalar but field_names expects {num_vals} additional values")
        elif isinstance(val, (list, tuple)):
            if len(val) != num_vals:
                raise ValueError(f"make_value returned {len(val)} values but field_names expects {num_vals}")
            val_seq = tuple(val)
        else:
            raise TypeError(f"make_value returned unsupported type {type(val)}")

        # determine the x coordinate
        if get_coordinate == "left":
            x_coord = low
        elif get_coordinate == "right":
            x_coord = up
        elif get_coordinate == "middle":
            x_coord = (low + up) / 2.0
        else:
            raise ValueError(f"Invalid get_coordinate: {get_coordinate!r}")

        # Append to graph fields
        graphed = [x_coord] + list(val_seq)
        for name, data in zip(field_names, graphed):
            graph[name].append(data)

    # ---------- handle scale ----------
    if scale is True:
        # Try to get scale attribute from histogram if present
        graph_scale = getattr(hist, "scale", None) or getattr(hist, "GetScale", lambda: None)()
    else:
        graph_scale = scale

    graph["scale"] = graph_scale
    return graph<|return|>

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is not __marker:
            return default
        raise
    del self[key]
    return value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        return super().popitem(last=False)
    except Exception as exc:
        raise TypeError("`self` must support OrderedDict-like popitem(last=False) behavior") from exc<|return|>

def popitem(self):
    """
    Remove and return the (key, value) pair most recently used.
    Behaves like dict.popitem(last=True) but raises KeyError on empty.
    """
    try:
        # Check if the container is empty
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        # Retrieve the most recent key (i.e., the last inserted/used)
        key = next(reversed(self))
    except Exception as exc:
        # Handle unexpected failures gracefully
        raise RuntimeError(
            f"Cannot determine the last key from {self!r}: {exc}"
        ) from exc
    # Remove and return the key-value pair
    try:
        return key, self.pop(key)
    except KeyError as exc:
        # This shouldn't happen but handle just in case
        raise KeyError(f"Key {key!r} not found during popitem") from exc
    except Exception as exc:
        raise RuntimeError(
            f"Error popping key {key!r} from {self!r}: {exc}"
        ) from exc<|return|>

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError("dictionary is empty")
    import random
    try:
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return key, value
    except Exception as exc:
        raise RuntimeError("failed to pop random item") from exc<|return|>

def isoparse(self, dt_str):
        """
        Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

        The implementation follows the behaviour of the original
        :func:`dateutil.parser.isoparse`.  It accepts the common
        ``YYYY``, ``YYYY-MM`` and ``YYYY-MM-DD`` forms, as well as the ISO
        week forms ``YYYYWww`` and ``YYYYWwwD``.  Time strings may be
        ``hh``, ``hhmm`` or ``hhmmss`` with optional fractional seconds
        and may be suffixed with a time‑zone offset, e.g. ``Z``,
        ``+HH:MM`` or ``-HHMM``.  24:00 is treated as midnight of the
        next day.  Any unspecified subcomponents are set to their lowest
        possible values.

        :param dt_str: a string containing a single ISO‑8601 datetime
            (or a stream which yields a single line).
        :return: :class:`datetime.datetime` instance with a tzinfo
            derived from the offset string (``tzutc`` for UTC, otherwise
            a ``tzoffset`` instance).  Hour ``24`` is converted to a
            min‑=0 and the next calendar day.
        """
        import datetime
        try:
            # Allow file‑like objects
            raw = getattr(dt_str, 'read', None)
            if callable(raw):
                content = raw()
            else:
                content = dt_str
            dt_str = content.strip()
        except Exception:
            raise ValueError("Invalid input for isoparse")

        # Split into date and optional time part
        sep_idx = None
        for i, ch in enumerate(dt_str):
            if ch in ('T', 't', ' '):
                sep_idx = i
                break
        if sep_idx is not None:
            date_part = dt_str[:sep_idx]
            time_part = dt_str[sep_idx + 1 :]
        else:
            date_part = dt_str
            time_part = ''

        def _parse_date(part):
            # ISO week date
            if 'W' in part or 'w' in part:
                # Expected forms: YYYY-Www or YYYYWww or with day
                num = part.replace('-', '').replace('W', '').replace('w', '')
                if len(num) < 6 or len(num) > 7:
                    raise ValueError("Invalid ISO week date format")
                year = int(num[:4])
                week = int(num[4:6])
                day = 1
                if len(num) == 7:
                    day = int(num[6])
                try:
                    return datetime.date(year, 1, 1).fromisocalendar(
                        year, week, day
                    )
                except Exception:
                    raise ValueError(f"Invalid ISO week date: {part}")
