def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Defensive programming: ensure request is provided
    if request is None:
        return False
    try:
        # 1. Check for a public message attribute
        if hasattr(request, 'public_message'):
            pub = getattr(request, 'public_message')
            if pub is not None:
                # If the public message is a mapping, look for common keys
                if isinstance(pub, dict):
                    if pub.get('type') == 'diaspora':
                        return True
                    if 'diaspora' in str(pub).lower():
                        return True
                # If it's a string or other object, string search
                if hasattr(pub, 'lower') and 'diaspora' in pub.lower():
                    return True
        # 2. Check for a private message attribute
        if hasattr(request, 'private_message'):
            priv = getattr(request, 'private_message')
            if priv is not None:
                if isinstance(priv, dict):
                    if priv.get('type') == 'diaspora':
                        return True
                    if 'diaspora' in str(priv).lower():
                        return True
                if hasattr(priv, 'lower') and 'diaspora' in priv.lower():
                    return True
        # 3. Check for a legacy marker
        # Some older payloads might have a boolean flag or a specific attribute
        if getattr(request, 'is_legacy', False):
            return True
        if getattr(request, 'legacy', False):
            return True
        if hasattr(request, 'legacy_payload'):
            # if legacy_payload is not empty or truthy
            legacy_payload = getattr(request, 'legacy_payload')
            if legacy_payload:
                return True
    except Exception:
        # On any unexpected error, treat as non-diaspora
        pass
    return False<|return|>

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    try:
        import datetime
        if dt is None:
            return None
        if not isinstance(dt, datetime.datetime):
            raise TypeError("Expected a datetime.datetime instance")
        # Use ISO 8601 with microseconds which is commonly expected by D* nodes
        return dt.isoformat(timespec="microseconds")
    except Exception as exc:
        raise ValueError(f"Unable to format datetime: {exc}") from exc<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        if not tag:
            return False
        # Tag must not start or end with a hyphen
        if tag[0] == '-' or tag[-1] == '-':
            return False
        # Check each character; only lowercase ASCII letters, digits, or hyphens are allowed
        prev_hyphen = False
        has_valid_char = False
        for ch in tag:
            if '0' <= ch <= '9':
                has_valid_char = True
                prev_hyphen = False
            elif 'a' <= ch <= 'z':
                has_valid_char = True
                prev_hyphen = False
            elif ch == '-':
                if prev_hyphen:  # consecutive hyphens are disallowed
                    return False
                prev_hyphen = True
            else:
                return False
        # Ensure at least one non-hyphen character exists
        return has_valid_char
    except Exception:
        return False<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # If node is None or not iterable, return empty dict
    if node is None:
        return {}
    children_dict = {}
    try:
        # Primary path: iterate over children directly
        for child in node:
            if hasattr(child, "tag"):
                children_dict[child.tag] = child
        return children_dict
    except Exception:
        # Fallback for objects that don't support iteration
        try:
            child_list = node.getchildren()
        except Exception:
            return {}
        for child in child_list:
            if hasattr(child, "tag"):
                children_dict[child.tag] = child
        return children_dict<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        if not isinstance(url, str):
            raise TypeError("url must be a string")
        url = url.strip()
        if not url.startswith(('http://', 'https://')):
            raise ValueError("url must start with http:// or https://")
        # Normalize base URL: strip trailing slash
        base = url.rstrip('/')
        if document_path is None:
            document_path = '/.well-known/nodeinfo'
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        document_path = document_path.strip()
        if not document_path:
            raise ValueError("document_path cannot be empty")
        # Ensure document path starts with '/'
        if not document_path.startswith('/'):
            document_path = '/' + document_path
        full_href = base + document_path
        # Construct the .well-known nodeinfo document
        nodeinfo = {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                    "href": full_href
                }
            ]
        }
        return nodeinfo
    except Exception as e:
        # Log the exception if needed (omitted here) and re‑raise
        raise e

