def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    def _strip_ns(tag: str) -> str:
        """Return the local part of an XML tag (without namespace)."""
        return tag.split("}", 1)[-1] if "}" in tag else tag

    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    result: Dict = {}
    # Try JSON first
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON document does not contain a top-level object")
        # Subject
        if "subject" in data:
            result["subject"] = data["subject"]
        # Aliases may appear as a list or a single string
        aliases = data.get("aliases")
        if aliases:
            if isinstance(aliases, list):
                result["aliases"] = aliases
            else:
                result["aliases"] = [aliases]
        # Links
        links = data.get("links")
        if isinstance(links, list):
            parsed_links = []
            for link in links:
                if isinstance(link, dict):
                    link_dict: Dict = {}
                    for key in ("rel", "type", "href", "template"):
                        if key in link:
                            link_dict[key] = link[key]
                    # Retain any additional keys that might be useful
                    for key, value in link.items():
                        if key not in link_dict:
                            link_dict[key] = value
                    if link_dict:
                        parsed_links.append(link_dict)
            if parsed_links:
                result["links"] = parsed_links
        return result
    except json.JSONDecodeError:
        pass  # Fall back to XML parsing

    # Try XML (XRD) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Document is neither valid JSON nor XML") from e

    aliases = []
    links = []
    subject = None

    for elem in root.iter():
        tag = _strip_ns(elem.tag)
        if tag == "Subject":
            subject = elem.text
        elif tag == "Alias":
            if elem.text:
                aliases.append(elem.text)
        elif tag == "Link":
            link_dict: Dict = {}
            for attr in elem.attrib:
                link_dict[attr] = elem.attrib[attr]
            # Capture <Attr name="..." value="..."/> children
            for child in elem:
                child_tag = _strip_ns(child.tag)
                if child_tag == "Attr":
                    name = child.attrib.get("name")
                    value = child.attrib.get("value")
                    if name:
                        link_dict[name] = value
            if link_dict:
                links.append(link_dict)

    if subject:
        result["subject"] = subject
    if aliases:
        result["aliases"] = aliases
    if links:
        result["links"] = links

    if not result:
        raise ValueError("Could not parse webfinger document")
    return result<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve (must contain an '@' character)
    :returns: dict
    """
    import re
    import json
    import xml.etree.ElementTree as ET
    from urllib.parse import quote_plus
    try:
        import requests
    except Exception:
        # requests not installed
        return {}

    # validate handle format
    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a string containing '@'")

    # encode handle for URL query
    resource = f"acct:{handle}"
    params = {'resource': resource}
    query = '&'.join([f"{k}={quote_plus(v)}" for k, v in params.items()])

    try:
        domain = handle.split('@', 1)[1]
    except Exception:
        return {}

    url = f"https://{domain}/.well-known/webfinger?{query}"
    try:
        response = requests.get(url, timeout=5, headers={'Accept': 'application/json, application/xrd+xml'})
        if response.status_code != 200:
            return {}
    except Exception:
        return {}

    content_type = response.headers.get('content-type', '')

    # JSON response
    if 'application/json' in content_type:
        try:
            return response.json()
        except Exception:
            return {}

    # XML response
    if 'xml' in content_type or 'xrd' in content_type:
        try:
            root = ET.fromstring(response.content)

            def elem_to_dict(elem):
                d = {}
                # attributes
                for k, v in elem.attrib.items():
                    d[k] = v
                # children
                children = list(elem)
                if children:
                    child_map = {}
                    for child in children:
                        name = child.tag
                        child_val = elem_to_dict(child)
                        if name in child_map:
                            if not isinstance(child_map[name], list):
                                child_map[name] = [child_map[name]]
                            child_map[name].append(child_val)
                        else:
                            child_map[name] = child_val
                    d.update(child_map)
                else:
                    text = elem.text
                    if text:
                        return text.strip()
                return d

            return {root.tag: elem_to_dict(root)}
        except Exception:
            return {}

    # Fallback: try JSON even if content-type omitted
    try:
        return json.loads(response.text)
    except Exception:
        return {}<|return|>

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Use only imports inside the function to avoid top‑level dependency.
    try:
        import requests
    except ImportError as exc:
        raise RuntimeError(
            "The 'requests' library is required to retrieve host-meta documents."
        ) from exc

    # Construct the well‑known host‑meta URL
    url = f"https://{host}/.well-known/host-meta"

    # Try HTTPS first, then fallback to HTTP if it fails
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception:
        # Fallback to HTTP
        url = f"http://{host}/.well-known/host-meta"
        try:
            resp = requests.get(url, timeout=10)
            resp.raise_for_status()
        except Exception as exc:
            raise RuntimeError(f"Unable to fetch host-meta from {host}") from exc

    # Parse the response body into an XRD object.
    try:
        text = resp.text
    except Exception as exc:
        raise RuntimeError("Failed to read response text") from exc

    # Attempt to use the XRD class provided by the diaspora package if available.
    # If not, fall back to a generic XML parsing approach.
    try:
        from diaspora import XRD
    except Exception:
        # No diaspora module, use xml.etree for a minimal fallback.
        from xml.etree import ElementTree as ET

        try:
            return ET.fromstring(text)
        except ET.ParseError as exc:
            raise ValueError("Response body is not valid XML") from exc
    else:
        try:
            return XRD(text)
        except Exception as exc:
            # If XRD cannot parse the string, try passing a file‑like object.
            try:
                from io import BytesIO
                return XRD(BytesIO(text.encode("utf-8")))
            except Exception:
                raise ValueError("Failed to parse host-meta XML into XRD") from exc
<|return|>

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1', 'key2')
      dict_insert({}, 'val', *'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    # normalize the key chain
    if key is None:
        raise ValueError("no key provided")
    # If key itself is iterable (but not string), treat as sequence of keys
    if isinstance(key, (list, tuple)) and not isinstance(key, str):
        key_chain = list(key) + list(keys)
    else:
        key_chain = [key] + list(keys)
    if not key_chain:
        raise ValueError("empty key chain")
    current = dic
    for k in key_chain[:-1]:
        if not isinstance(k, (str, int, float, bool)):
            raise TypeError(f"key {k!r} is not hashable")
        if k not in current or not isinstance(current.get(k), dict):
            current[k] = {}
        current = current[k]
    last_key = key_chain[-1]
    if not isinstance(last_key, (str, int, float, bool)):
        raise TypeError(f"final key {last_key!r} is not hashable")
    current[last_key] = val
    return dic<|return|>

