        # Determine required fields: use class attribute if present, otherwise default
        required_fields = getattr(cls, "REQUIRED_FIELDS", ("metadata",))
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

        return data

