@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No YAML file path provided.")

        try:
            with open(yaml_file, "r", encoding="utf-8") as fh:
                data = yaml.safe_load(fh)
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
        except yaml.YAMLError as exc:
            raise IRValidatorException(f"Error parsing YAML file: {yaml_file}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a top-level dictionary.")

        required = getattr(cls, "required_fields", None)
        if required:
            missing = [field for field in required if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required fields in YAML file: {', '.join(missing)}"
                )

        return data<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Assume the spec is stored in self.spec and is a mapping of arguments.
        spec = getattr(self, 'spec', {})
        if not isinstance(spec, dict):
            return defaults

        for name, info in spec.items():
            # If the spec entry is itself a mapping with a 'default' key, use that.
            if isinstance(info, dict):
                if 'default' in info:
                    defaults[name] = info['default']
                else:
                    # Try to use the entire dict as default if no explicit default.
                    defaults[name] = info
            else:
                # If the spec is a scalar, treat it as the default value.
                defaults[name] = info

    except Exception as e:
        # Log the exception and re‑raise with a helpful message.
        import logging
        logging.exception("Failed to resolve spec defaults: %s", e)
        raise

    return defaults

