def validate_arg_deprecation(self, cli_args, answer_file_args):
        """
        Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """

        # Define a mapping of deprecated argument names to their replacement description
        # (This can be extended as needed by the surrounding codebase.)
        DEPRECATED_ARGS = {
            "old_flag": "Use 'new_flag' instead.",
            "legacy_option": "Use 'updated_option' instead.",
            "deprecated_mode": "Use 'mode' instead."
        }

        # Helper function to accumulate deprecated args from a given source
        def _gather_deprecated(source, source_name):
            if not isinstance(source, dict):
                raise TypeError(f"{source_name} must be a dictionary, got {type(source).__name__}")
            deprecated = {}
            for key in source:
                if key in DEPRECATED_ARGS:
                    deprecated[key] = DEPRECATED_ARGS[key]
            return deprecated

        try:
            cli_deprecated = _gather_deprecated(cli_args, "cli_args")
            file_deprecated = _gather_deprecated(answer_file_args, "answer_file_args")

            # Merge deprecated args while preserving the source of each
            merged_deprecated = {}
            for src_key, src_dict in (("CLI", cli_deprecated), ("Answer file", file_deprecated)):
                for arg, msg in src_dict.items():
                    merged_deprecated[arg] = (src_key, msg)

            if merged_deprecated:
                print("Deprecated arguments detected:")
                for arg, (src, msg) in merged_deprecated.items():
                    print(f"  - {arg} (provided via {src}): {msg}")
            else:
                # No deprecated arguments found; nothing to print
                pass

        except Exception as exc:
            # If an unexpected error occurs, raise an informative exception
            raise RuntimeError(f"Error validating deprecated arguments: {exc}") from exc
<|return|>

