def get_silent_args(self, args):
    """list of silenced argument

    >>> self.get_silent_args({'a': None, 'b': 2, 'c': None})
    ['a', 'c']

    :param args: The received arguments; may be a dict, argparse.Namespace,
                 or any mapping-like object.
    :return: list of argument names considered "silent" (values are None).
    """
    if args is None:
        raise ValueError("args cannot be None")
    silent_args = []

    # Determine the key-value iterable depending on the args type
    try:
        if isinstance(args, dict):
            items = args.items()
        elif hasattr(args, "__dict__"):
            items = args.__dict__.items()
        else:
            # Fallback: try to iterate directly; expect (key, value) pairs
            items = list(args)
    except Exception as e:
        raise TypeError(f"Unsupported type for args: {type(args).__name__}") from e

    for key, val in items:
        if isinstance(key, str) and key.startswith("_"):
            # Skip internal or private attributes
            continue
        try:
            if val is None:
                silent_args.append(key)
        except Exception:
            # If comparison raises, ignore this item
            continue

    return silent_args<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the set of required arguments; if none are defined, nothing to check.
    required = getattr(self, 'required_args', None)
    if not required:
        return True
    # Ensure args is a mapping; if None, treat as empty.
    if args is None:
        args = {}
    # If args is not a dict, try to coerce it to a dict (e.g., from list of tuples).
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError("Provided args must be a mapping or iterable of key/value pairs.") from exc
    missing = set(required) - set(args.keys())
    if missing:
        missing_list = ', '.join(sorted(missing))
        raise ValueError(f"Missing required arguments: {missing_list}")
    return True<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
