                    continue
                required_when = opt.get('required_when')
                if not required_when:
                    continue

                # The option's name is expected under the key 'name'
                opt_name = opt.get('name')
                if not opt_name:
                    continue

                # Handle condition expressed as a callable
                if callable(required_when):
                    try:
                        if required_when(args):
                            required_args.append(opt_name)
                    except Exception:
                        # ignore failures in condition evaluation
                        continue
                    continue

                # Handle condition expressed as a mapping
                if isinstance(required_when, dict):
                    try:
                        match = True
                        for key, expected in required_when.items():
                            if key not in args:
                                match = False
                                break
                            actual = args[key]
                            # If expected is a collection, check membership
                            if isinstance(expected, (list, tuple, set)):
                                if actual not in expected:
                                    match = False
                                    break
                            else:
                                if actual != expected:
                                    match = False
                                    break
                        if match:
                            required_args.append(opt_name)
                    except Exception:
                        continue
            return required_args
        except Exception:
            # On any unexpected error, return an empty list to avoid breaking elsewhere
            return []<|return|>

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :return: True if all arguments satisfy their length constraints.
    :raises TypeError: If `args` is not a mapping or if spec is invalid.
    :raises ValueError: If any value exceeds its specified maximum length.
    """
    # Ensure args is a mapping (dict-like)
    try:
        if not hasattr(args, "__iter__") or isinstance(args, (str, bytes)):
            raise TypeError("args must be a mapping of keys to values")
        args_items = dict(args)  # convert to a plain dict if possible
    except Exception as exc:
        raise TypeError(f"Failed to process args as mapping: {exc}") from exc

    # Determine the specification of maximum lengths
    spec = None
    for name in ("length_spec", "max_lengths", "length_args"):
        spec = getattr(self, name, None)
        if isinstance(spec, dict):
            break
    if spec is None:
        # No length specification: treat all as unlimited
        spec = {}

    # Validate each argument
    for key, value in args_items.items():
        try:
            # Determine string representation length if printable
            if isinstance(value, (str, bytes)):
                val_len = len(value)
            elif hasattr(value, "__len__"):
                # For sequences or collections
                val_len = len(value)
            else:
                # Non-lengthable objects are considered fine
                continue
        except Exception as exc:
            raise ValueError(f"Cannot measure length of argument '{key}': {exc}") from exc

        max_len = spec.get(key)
        if isinstance(max_len, int) and max_len > 0:
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{key}' exceeds maximum length of {max_len} (actual: {val_len})"
                )

    return True<|return|>

def validate_choices_args(self, args):
    """
    Check if the value(s) of choice arguments are one of the available choices.

    Parameters
    ----------
    args : dict or object with ``__dict__``
        The received arguments. Keys are argument names and values are the
        supplied values.

    Raises
    ------
    ValueError
        If any argument that has a set of allowed choices receives a value
        not included in those choices.
    TypeError
        If ``args`` is neither a mapping nor an object with a ``__dict__``.
    """
    if args is None:
        raise ValueError("The 'args' parameter must not be None.")

    # Convert args to a plain dictionary if possible
    if isinstance(args, dict):
        arg_dict = args
    elif hasattr(args, "__dict__"):
        arg_dict = vars(args)
    else:
        raise TypeError("Argument 'args' must be a dict or an object with a '__dict__' attribute.")

    # If no constraints are defined, there's nothing to validate
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        return

    for key, value in arg_dict.items():
        if key not in self.choices:
            continue  # argument not governed by choice constraints

        allowed = set(self.choices[key])
        if isinstance(value, (list, tuple, set)):
            # If a collection of values was supplied, each must be allowed
            invalid_values = [v for v in value if v not in allowed]
            if invalid_values:
                raise ValueError(
                    f"Argument '{key}' received invalid values {invalid_values}. "
                    f"Allowed values are {sorted(allowed)}."
                )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Argument '{key}' has invalid value {value!r}. "
                    f"Allowed values are {sorted(allowed)}."
                )<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Optionally, perform minimal spec validation
    # e.g., spec_option should contain a 'type' key
    if 'type' not in spec_option:
        raise ValueError("spec_option missing required 'type' key")

    # Define a simple complex argument class if one does not already exist
    try:
        ComplexArgument  # Check if it exists in context
    except NameError:
        class ComplexArgument:
            """A lightweight container for complex argument data."""
            def __init__(self, subcommand, type_name, option_name, spec):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                self.spec = spec

            def __repr__(self):
                return (f"<ComplexArgument subcommand={self.subcommand!r} "
                        f"type_name={self.type_name!r} "
                        f"option_name={self.option_name!r} "
                        f"spec={self.spec!r}>")

    try:
        obj = ComplexArgument(subcommand, type_name, option_name, spec_option)
    except Exception as exc:
        raise RuntimeError(f"Failed to create ComplexArgument: {exc}") from exc

    return obj<|return|>

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args (dict, list of tuples, or Namespace).
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Convert various possible input types to a plain dictionary
        try:
            if isinstance(args, dict):
                arg_dict = dict(args)  # shallow copy
            elif isinstance(args, (list, tuple)):
                # Assume list of (key, value) tuples
                arg_dict = {k: v for k, v in args if isinstance(k, str)}
            elif hasattr(args, "__dict__"):
                # argparse.Namespace or similar
                arg_dict = {k: v for k, v in vars(args).items() if isinstance(k, str)}
            else:
                # Unsupported type: return empty dicts
                return {}, {}
        except Exception:
            return {}, {}

        # Prepare the two output dictionaries
        control_args = {}
        nested_args = {}

        # Define heuristics for control arguments
        # Keys that start with a single underscore or "control_" are considered control arguments
        for key, value in arg_dict.items():
            if value is None:
                # Skip keys with None value
                continue
            if key.startswith("_") or key.startswith("control_"):
                control_args[key] = value
            else:
                # All other keys are nested arguments.
                # For custom arguments prefixed with "custom_" we simply store them
                # under nested_args but preserve the key name.
                nested_args[key] = value

        return control_args, nested_args
<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Import inside the function to avoid top-level imports
    from pathlib import Path
    import json
    try:
        import yaml  # type: ignore
    except Exception:
        yaml = None

    # Resolve path
    try:
        dir_path = Path(plugin_dir)
    except Exception as e:
        raise TypeError(f"plugin_dir must be a path-like object or string, got {type(plugin_dir)}") from e

    if not dir_path.is_dir():
        raise FileNotFoundError(f"Plugin directory does not exist: {plugin_dir}")

    # Spec file candidates
    candidates = ["plugin.yaml", "plugin_spec.yaml", "spec.yaml", "plugin.json", "spec.json"]
    spec_file = None
    for name in candidates:
        candidate_path = dir_path / name
        if candidate_path.is_file():
            spec_file = candidate_path
            break

    if spec_file is None:
        raise FileNotFoundError(
            f"No plugin spec file found in directory '{plugin_dir}'. "
            f"Looked for: {', '.join(candidates)}"
        )

    # Load spec content
    spec_data = None
    try:
        with spec_file.open("r", encoding="utf-8") as f:
            if spec_file.suffix.lower() in (".yaml", ".yml"):
                if yaml is None:
                    raise RuntimeError("PyYAML is required to parse YAML plugin specs")
                spec_data = yaml.safe_load(f)
            elif spec_file.suffix.lower() == ".json":
                spec_data = json.load(f)
            else:
                raise ValueError(f"Unsupported spec file format: {spec_file.suffix}")
    except Exception as exc:
        raise ValueError(f"Failed to read or parse plugin spec file '{spec_file}': {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec root must be a mapping/dict, got {type(spec_data)}")

    # Helper to flatten nested dicts/lists
    def _flatten(current, parent_key=""):
        items = {}
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else str(k)
                items.update(_flatten(v, new_key))
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                items.update(_flatten(item, new_key))
        else:
            items[parent_key] = current
        return items

    flat_dict = _flatten(spec_data)
    return flat_dict
<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
    except Exception as exc:
        raise RuntimeError("Required modules for environment configuration are unavailable.") from exc

    # Name of the environment variable that should hold the config path
    env_var = "CONFIG_PATH"

    # Determine a default path.  Prefer an attribute on the instance, fall back to a
    # relative path based on the current file location.
    default_path = getattr(self, "default_config_path", None)
    if not isinstance(default_path, str) or not default_path:
        # Construct a safe fallback path
        try:
            current_dir = os.path.dirname(__file__) if "__file__" in globals() else os.getcwd()
        except Exception:
            current_dir = os.getcwd()
        default_path = os.path.join(current_dir, "config.ini")

    # If the variable is not set (or set to an empty string), set it
    if not os.environ.get(env_var):
        try:
            os.environ[env_var] = default_path
        except Exception as exc:
            raise RuntimeError(f"Unable to set environment variable '{env_var}'.") from exc
    # No explicit return needed; the method performs side‑effects only.<|return|>

def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    """
    # Validate input types
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")
    if not isinstance(root, str):
        raise TypeError(f"root must be a string, got {type(root).__name__}")
    if root == "":
        raise ValueError("root cannot be empty")
    # Normalize root: strip trailing separator unless it is just the root separator
    sep_chars = ('/', '\\')
    if root != sep_chars[0] and root.endswith(sep_chars):
        root = root.rstrip('/\\')
    # Check whether path starts with root and is correctly separated
    if path == root:
        remainder = ""
    elif path.startswith(root) and len(path) > len(root) and path[len(root)] in ("/", "\\"):
        remainder = path[len(root):]
    else:
        raise ValueError(f"'{path}' does not start with the specified root '{root}'")
    # Strip leading separators from the remainder
    remainder = remainder.lstrip('/\\')
    return remainder
<|return|>
